def proof(root):
 raw=core.path(root,EP).read_bytes();core.need(core.H(raw)==PROOF_SHA,'近系proof SHA');return json.loads(raw)
def effective(parent,root):
 if not(Path(root)/EP).is_file():return parent
 import copy
 b=proof(root);core.need(core.H(core.path(root,core.EP).read_bytes())==b['parent_ner_sha256'],'近系corrected58names NER前置')
 out=copy.deepcopy(parent)
 for k,v in b['annotation_additions'].items():core.need(k not in out['chapter_template']['annotation'],'近系annotation衝突');out['chapter_template']['annotation'][k]=v
 out['groups_template']['unresolved_readings']+=b['group_reading_additions']
 return out
def sex_reference(root):
 b=proof(root)
 for rel,h in b['reference_pins'].items():core.need(core.H(core.path(root,rel).read_bytes())==h,'蔡邕參讀capture SHA '+rel)
 ref=core.read(root,core.BASE+'kinship-references/caiyong-sex-reading.json');unit=core.path(root,ref['unit_projection_path']).read_text()
 core.need(ref['actual_access']=='current_rendered_tool_response'and ref['fixed_revision_content_retrieved']is False and ref['raw_retrieved']is False and ref['raw_sha256']is None and ref['edition']is None and ref['image_verified']is False and ref['human_reviewed']is False,'蔡邕性別參讀取得/版本資格不得升格')
 core.need('同郡蔡邕之女也，名琰，字文姬'in unit and '文姬曰：「昔亡父賜書四千許卷'in unit and '心怛絕兮死復生'in unit,'蔡邕父角色須完整蔡文姬單元，非男性外孫或女字單推')
 core.need(ref['identity_and_sex_reading']['subject_source_role']=='cai_yong'and ref['identity_and_sex_reading']['sex_preference']=='male','獨立父角色性別讀法')
def documents(root,r,ch):
 if not(Path(root)/EP).is_file():return None
 b=proof(root);core.need(ch['annotation'].get('fixed_jin034_close_kin_ref')==EP,'近系active章ref')
 core.need(core.same(b['group_reading_additions'],QUALIFIED_READING_SEMANTICS),'近系qualified母系/拒嗣讀法不得自洽換義或增未知reading')
 sex_reference(root)
 for rel,t in b['expected_documents'].items():
  d=core.read(root,rel);core.need(core.same(d,core.expand(t,r)),'近系sidecar缺/額外/單端漂移 '+rel)
  for rec in d.get('assertions',d.get('reports',[])):
   for e in rec['evidence']:
    p,=[p for p in ch['paragraphs']if p['id']==e['paragraph_id']];core.need(e['quote']==p['text']and e['chapter_id']==ch['id']and all(e[k]==ch[k]for k in('work_id','book_id','source_id')),'近系完整段/來源維度')
    ms={m['id']:m for m in p['mentions']}
    for field,endpoint in [('subject_person_mention_id','subject_person_id'),('object_person_mention_id','object_person_id'),('reference_person_mention_id','reference_person_id')]:
     if field in e:
      m=ms[e[field]];core.need(m['kind']=='person'and m['person_id']==rec[endpoint]and p['text'][m['start']:m['end']]==m['surface'],'近系角色MID端點')
    if 'count_anchor'in e:
     q=e['count_anchor'];core.need(type(q['start'])is int and type(q['end'])is int and p['text'][q['start']:q['end']]==q['surface'],'來源報數範圍')
  if d['record_type']=='person_assertion_set':
   core.need(len(d['assertions'])==len(SEMANTICS),'近系有限方向數')
   for rec in d['assertions']:
    slot=rec['qualifiers']['source_clause_binding']['slot'];sub,pred,obj=SEMANTICS[slot]
    core.need((rec['subject_person_id'],rec['predicate'],rec['object_person_id'])==(r[sub],pred,r[obj]),'近系獨立角色主客方向')
    core.need(core.same(rec['qualifiers'],core.expand(QUALIFIERS[slot],r)),'近系原詞/母系/長幼/未知父與生母界限')
    para,term=LOCATIONS[slot];core.need(rec['evidence'][0]['paragraph_id']==para and term in rec['evidence'][0]['quote'],'近系原句位置')
  else:
   core.need(d['owner']=='fixed_jin034_yanghu_ner'and len(d['reports'])==len(COUNT_SEMANTICS),'來源報數owner/slots')
   for rec in d['reports']:
    expected=core.expand(COUNT_SEMANTICS[rec['id']],r);core.need(core.same({k:v for k,v in rec.items()if k!='evidence'},expected),'來源報數/存在/世距/故事範圍不得自洽改義')
    if rec['reported_count']is not None:core.need(type(rec['reported_count'])is int,'報數不得bool/浮數')
 return b
@memoized(0)
def state(root):
 b,r,people,ch=core.accepted_state(root);p=documents(root,r,ch);core.need(p is not None,'近系phase缺');return p,r,people,ch
def applies(a):return any(e.get('chapter_id')==core.CID or str(e.get('paragraph_id','')).startswith(core.CID+':')for e in a.get('evidence',[]))or a.get('qualifiers',{}).get('source_clause_binding',{}).get('rule')==RULE
def valid(a,paragraphs,root):
 try:
  b,r,people,ch=state(root);expected=core.expand(b['expected_documents'][AP],r)['assertions'];core.need(any(core.same(a,x)for x in expected),'未知近系assertion/slot')
  for e in a['evidence']:
   p,=[p for p in ch['paragraphs']if p['id']==e['paragraph_id']];hit=paragraphs.get(p['id']);core.need(hit is not None and hit[0]==ch['id']and core.same(hit[1],p),'近系caller完整段與字位')
  return True
 except(ValueError,KeyError,TypeError,OSError,IndexError,StopIteration,AttributeError):return False
def caller(records,people,root,b,r,actual,ch):
 core.need(isinstance(records,list)and isinstance(people,dict),'近系caller catalog')
 for pid,p in actual.items():core.need(core.same(people.get(pid),p),'近系caller角色metadata/reverse')
 core.need(core.same([x for x in records if x.get('id')==core.CID],[ch]),'近系caller完整章')
 for key in('names_path','identities_path','groups_path'):
  expected=core.read(root,core.fixed(root)[key]);core.need(core.same([x for x in records if x.get('record_type')==expected['record_type']and x.get('chapter_id')==core.CID],[expected]),'近系caller NER側車')
 for rel,t in b['expected_documents'].items():
  expected=core.expand(t,r);core.need(core.same([x for x in records if x.get('record_type')==expected['record_type']and x.get('chapter_id')==core.CID],[expected]),'近系caller完整assertions/counts')
def counts(records,people,root,ids):
 docs=[x for x in records if x.get('record_type')=='source_family_count_report_set']
 if not(Path(root)/EP).is_file():core.need(not docs,'orphan034報數');return []
 if not docs and not any(x.get('chapter_id')==core.CID or x.get('id')==core.CID for x in records) and not(set(ids)&set(core.source_index(root)['person_ids'])):return []
 b,r,actual,ch=state(root);caller(records,people,root,b,r,actual,ch);core.need(all(x.get('owner')=='fixed_jin034_yanghu_ner'and x.get('chapter_id')==core.CID for x in docs),'未知034報數owner')
 return [x for x in core.expand(b['expected_documents'][CP],r)['reports']if x['reference_person_id']in ids]
def guard_bundle(root,pid,people,records):
 if not(Path(root)/EP).is_file()or pid not in core.source_index(root)['person_ids']:return
 b,r,actual,ch=state(root);caller(records,people,root,b,r,actual,ch)
